/**
 * Fixed Empire-win seeds for W9 (SWR-006 test-cases.md TC-OUT-04/05/06): `E-HUNT` (full-knowledge human Empire)
 * vs AI Rebels easy / normal on `DIFF_SEEDS`, played through the server module's automation with the `bot`
 * strategy (`../harness`). Data: `./empire-win-seeds.json` (generated by `fixtures.test.ts` with
 * `UPDATE_SIM_FIXTURES=1`, verified on every normal run). Each entry carries the human Empire's exact command
 * sequence, so the API test can replay it through `POST /api/sessions/:id/commands` (same `sessionId`, settings
 * `playerFaction: 'empire'`, `opponentType: 'ai'`, `aiDifficulty`, `ruleset: 'base'`, `gameMode: 'digital'`) and
 * expect the same end: `winner: 'empire'`, `reason: 'rebelBaseCaptured'`, `finalVersion`.
 * The bot does not depend on `now` (its seed is `sessionId#version`), so the API clock does not matter.
 */
import type { CoreCommand } from '../../../../src/schema';
import data from './empire-win-seeds.json';

export interface EmpireWinSeed {
  readonly sessionId: string;
  /** The true base (test oracle — never compare it with an Empire-facing response before the reveal). */
  readonly base: string;
  readonly winner: 'empire';
  readonly reason: 'rebelBaseCaptured';
  /** `state.round` / `state.version` at the end of the game. */
  readonly finalRound: number;
  readonly finalVersion: number;
  /** The human Empire's commands in order (each sent with `expectedVersion` = the current version). */
  readonly humanCommands: readonly CoreCommand[];
}

export interface EmpireWinSeeds {
  readonly script: 'E-HUNT';
  readonly aiSide: 'rebels';
  readonly easy: readonly EmpireWinSeed[];
  readonly normal: readonly EmpireWinSeed[];
}

export const EMPIRE_WIN_SEEDS = data as EmpireWinSeeds;

/** test-cases.md TC-OUT-06: the first winning seed of each difficulty. */
export const WIN_SEED_EASY = EMPIRE_WIN_SEEDS.easy[0]?.sessionId;
export const WIN_SEED_NORMAL = EMPIRE_WIN_SEEDS.normal[0]?.sessionId;
